__NUXT_JSONP__("/desarrollo-sostenible/noticias/presidenciales_plantean_mantener_programas_sociales_pero_necesitan_mas_ingresos", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u){return {data:[{post:{slug:"presidenciales_plantean_mantener_programas_sociales_pero_necesitan_mas_ingresos",title:"Presidenciales plantean mantener programas sociales, pero necesitan más ingresos",date:"2024-05-14T14:55:24.942Z",img:"https:\u002F\u002Fucarecdn.com\u002F0c857ea6-535a-4d45-a161-75c5a4d5a383\u002F","img-alt":"Candidatas presidenciales México",autor:"Dulce Soto, Expansión",link:"https:\u002F\u002Fpolitica.expansion.mx\u002Felecciones\u002F2024\u002F05\u002F11\u002Fque-haran-candidatos-presidenciales-programas-sociales",category:"desarrollo-sostenible",extracto:"Especialistas en finanzas públicas señalan que son inviables las promesas de campaña de las candidaturas presidenciales sin una reforma fiscal.",toc:[{id:o,depth:f,text:p},{id:q,depth:f,text:r},{id:s,depth:f,text:t}],body:{type:"root",children:[{type:b,tag:d,props:{},children:[{type:a,value:"Los "},{type:b,tag:e,props:{},children:[{type:a,value:"programas sociales"}]},{type:a,value:" prioritarios del presidente Andrés Manuel López Obrador se mantendrían en el "},{type:b,tag:e,props:{},children:[{type:a,value:"siguiente sexenio"}]},{type:a,value:" sin importar qué candidatura gane la elección presidencial. Al menos eso se ha prometido en las campañas electorales."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Tanto Claudia Sheinbaum, candidata presidencial de Morena-PVEM-PT, como Xóchitl Gálvez, del PAN-PRI-PRD, y Jorge Álvarez Máynez, de Movimiento Ciudadano (MC), se han posicionado a favor de mantener la pensión para las personas adultas mayores, las becas de estudiantes y han propuesto nuevos apoyos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Sin embargo, especialistas explican que cumplir estas promesas requiere mayores ingresos gubernamentales porque con los actuales hay poco margen de maniobra y las transferencias monetarias representan un alto gasto."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“Sí nos tiene que preocupar el financiamiento de los programas sociales, más aún, estos programas que se están proponiendo. Por ejemplo, en este gobierno, de 2019 a 2024, el presupuesto asignada a las pensiones de personas adultas mayores aumentó tres veces. pasamos de 0.4% del PIB a 1.33% del PIB”, alerta Liliana Alvarado, directora general de Ethos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Pero las candidatas han afirmado que no implementarán una reforma fiscal ni cobrarán más impuestos. Máynez es el único candidato que sí promete abiertamente una modificación hacendaria, pero las especialistas consideran que falta robustecer su planteamiento."}]},{type:a,value:c},{type:b,tag:g,props:{},children:[{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Es contradictorio como, por un lado, se habla de austeridad, pero, por otro, se habla de programas sociales ambiciosos y no se habla de cómo se van a financiar\","}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Liliana Alvarado, directora general de Ethos."}]},{type:a,value:c},{type:b,tag:h,props:{id:o},children:[{type:b,tag:i,props:{ariaHidden:j,href:"#las-propuestas-contra-la-pobreza",tabIndex:k},children:[{type:b,tag:l,props:{className:[m,n]},children:[]}]},{type:b,tag:e,props:{},children:[{type:a,value:p}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Para disminuir la pobreza en México, donde 36.3 millones de personas está en situación de pobreza y 7.1 millones en pobreza extrema, Claudia Sheinbaum propone otorgar un apoyo económico a las mujeres de 60 a 64 años similar al programa universal Pensión para el Bienestar de las Personas Adultas Mayores."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"También plantea dar apoyos a mujeres artesanas, en especial indígenas; elevar el salario mínimo a 2.5 canastas básicas y llevar a todo el país la Beca Bienestar para Niños y Niñas, para alumnas y alumnos de educación básica de preescolar a secundaria implementada en su gobierno de la Ciudad de México."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Además promete seguridad social para jornaleros y jornaleras agrícolas, así como repartidores; aumentar todos los programas sociales cada año por encima de la inflación y llevarlos a la Constitución mexicana."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En el mismo rubro, Xóchitl Gálvez plantea mantener los programas sociales actuales; crear un programa alimentario para comunidades marginadas con el fin de reducir la pobreza extrema y dar una beca universal para todos los niños y niñas de escuelas públicas y privadas, desde preescolar a preparatoria."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Otras de sus propuestas son dar apoyos económicos a mujeres en condiciones de vulnerabilidad y otorgar la pensión de adultos mayores a partir de los 60 años, cinco años más temprano que lo establecido actualmente en el programa."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Jorge Álvarez Máynez propone aumentar el salario mínimo hasta llegar a los 10,000 pesos al mes; duplicar el presupuesto para la primera infancia y las becas a estudiantes, además de mantener los programas sociales de pensiones."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“Todas esas medidas cuestan\", dice Alvarado."}]},{type:a,value:c},{type:b,tag:h,props:{id:q},children:[{type:b,tag:i,props:{ariaHidden:j,href:"#la-situaci%C3%B3n-econ%C3%B3mica",tabIndex:k},children:[{type:b,tag:l,props:{className:[m,n]},children:[]}]},{type:b,tag:e,props:{},children:[{type:a,value:r}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"A decir de Dalia Toledo, directora de Finanzas Públicas y Anticorrupción, las carencias sociales y económicas de la población mexicana no se superarán con los niveles tributarios actuales, que representan el 17.3% del Producto Interno Bruto (PIB) mientras que el promedio de los países de la Organización para la Cooperación y el Desarrollo Económicos (OCDE) es de 34.2%."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"A esto se suma una mayor presión del gasto por los programas sociales, las megaobras y las pensiones, en las que se invierte uno de cada cinco pesos de todo el presupuesto del gobierno, explicó. Para 2024, el Gobierno federal cerrará con un déficit presupuestario equivalente al 5.4% del PIB."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Pese a este panorama complejo para las finanzas públicas, las dos candidatas a la Presidencia de la República has descartado implementar una reforma fiscal que garantice finanzas gubernamentales sostenibles."}]},{type:a,value:c},{type:b,tag:g,props:{},children:[{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Observamos una contradicción discursiva porque se dice que va a haber austeridad, pero, por el otro lado, las propuestas sociales implican un mayor gasto público”,"}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Dalia Toledo, directora de Finanzas Públicas y Anticorrupción"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Máynez sí ha propuesto una reforma fiscal, pero considera que todavía no se aprecian los alcances que tendría."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“Salvo el candidato de Movimiento Ciudadano que sí reconoce la importancia de una reforma fiscal, aunque solo nos habla de los impuestos al tabaco, los impuestos verdes. Esta propuesta del candidato Máynez sí va por el camino correcto, sin embargo, los alcances ahorita no son muy claros y no nos va a alcanzar solo con impuestos al tabaco para recaudar todos los recursos que México necesita para tener finanzas sostenibles”, expone Toledo."}]},{type:a,value:c},{type:b,tag:h,props:{id:s},children:[{type:b,tag:i,props:{ariaHidden:j,href:"#m%C3%A1s-gasto-menos-focalizaci%C3%B3n",tabIndex:k},children:[{type:b,tag:l,props:{className:[m,n]},children:[]}]},{type:b,tag:e,props:{},children:[{type:a,value:t}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Para Laure Delalande, directora de Inclusión y Desarrollo Sostenible, otro problema es que los programas sociales actuales no han sido tan efectivos en el combate a la pobreza."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Lo anterior, explica, porque perdieron la capacidad de llegar a las personas que más necesitan estos apoyos porque ampliar el universo de posibles beneficiarios."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Esta capacidad sí estaba en los programas de otros sexenios, pese a las fallas que tenía en su diseño."}]},{type:a,value:c},{type:b,tag:g,props:{},children:[{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"La política social de los sexenios anteriores no era buena, pero teníamos la capacidad de focalizar y esta capacidad se perdió por completo\","}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Laure Delalande, directora de Inclusión y Desarrollo Sostenible"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En este momento ningún programa aplica este tipo de metodología porque se considera que los programas son universales, explica."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"\"Independientemente de tu ingreso, tú puedes tener acceso al programa, y eso sí nos pone en peligro en términos de finanzas públicas, porque hace que el universo poblacional sea muy amplio”, advierte."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Por otro lado, aunque estos apoyos se reparten por medio de transferencias directas, bancarizadas, que es un modo de operar menos propicio para prácticas de corrupción, operan sin transparencia."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“Este gobierno ha operado en una opacidad enorme. Entonces, la oportunidad que tenía este gobierno de comprobarnos que realmente había menos problemas de corrupción la perdió porque nadie confía, no nos dan información y ya hemos visto algunos casos de corrupción”, dice."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fpresidenciales_plantean_mantener_programas_sociales_pero_necesitan_mas_ingresos",extension:".md",createdAt:u,updatedAt:u}}],fetch:{},mutations:[]}}("text","element","\n","p","strong",2,"blockquote","h2","a","true",-1,"span","icon","icon-link","las-propuestas-contra-la-pobreza","Las propuestas contra la pobreza","la-situación-económica","La situación económica","más-gasto-menos-focalización","Más gasto, menos focalización","2024-10-02T22:32:44.095Z")));